const DICTS: Record<LangCode, Dict> = { en, es, pt, fr, de, ru, zh, ja, ko, hi, tr, id, it, pl, vi };

// ---- Current language (remembered between visits) ----
const LANG_KEY = 'vb-lang';
function isLang(v: unknown): v is LangCode { return typeof v === 'string' && v in DICTS; }
function detect(): LangCode {
  try {
    const saved = localStorage.getItem(LANG_KEY);
    if (isLang(saved)) return saved;
  } catch { /* storage blocked */ }
  try {
    const nav = (typeof navigator !== 'undefined' ? navigator.language : '') || '';
    const short = nav.toLowerCase().split('-')[0];
    if (isLang(short)) return short;
  } catch { /* ignore */ }
  return 'en';
}
let current: LangCode = detect();
const listeners = new Set<() => void>();

export function getLanguage(): LangCode { return current; }
export function setLanguage(code: LangCode) {
  if (!isLang(code) || code === current) return;
  current = code;
  try { localStorage.setItem(LANG_KEY, code); } catch { /* storage blocked */ }
  try { document.documentElement.lang = code; } catch { /* no document */ }
  for (const l of listeners) l();
}

/** Looks a string up in the current language (English if it's missing), filling in {name} style gaps. */
export function t(key: string, vars?: Record<string, string | number>): string {
  let s = DICTS[current][key] ?? en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

/** Re-renders the component whenever the language changes. Returns the current language. */
export function useLanguage(): LangCode {
  return useSyncExternalStore(
    (cb) => { listeners.add(cb); return () => { listeners.delete(cb); }; },
    () => current,
    () => 'en' as LangCode,
  );
}

/** For tests: every language must have the same keys as English. */
export function missingKeys(code: LangCode): string[] {
  return Object.keys(en).filter((k) => !(k in DICTS[code]));
}
